#include "cvc_json.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <math.h>
#include <stdarg.h>

typedef struct { const unsigned char *p; size_t n,pos,line,col; char *err; } P;
static void fail(P*q,const char*fmt,...){if(q->err)return;va_list ap;va_start(ap,fmt);char body[256];vsnprintf(body,sizeof(body),fmt,ap);va_end(ap);char full[384];snprintf(full,sizeof(full),"line %zu column %zu byte %zu: %s",q->line,q->col,q->pos,body);q->err=cvc_xstrdup(full);}
static int eof(P*q){return q->pos>=q->n;}
static unsigned char peek(P*q){return eof(q)?0:q->p[q->pos];}
static unsigned char getc_p(P*q){if(eof(q))return 0;unsigned char c=q->p[q->pos++];if(c=='\n'){q->line++;q->col=1;}else q->col++;return c;}
static void ws(P*q){while(!eof(q)){unsigned char c=peek(q);if(c==' '||c=='\t'||c=='\r'||c=='\n')getc_p(q);else break;}}
static CvcJson*node(CvcJsonType t){CvcJson*j=cvc_xcalloc(1,sizeof(*j));j->type=t;return j;}
static void emit_cp(P*q,CvcBuf*b,uint32_t cp){if(cp<=0x7f)cvc_buf_putc(b,(unsigned char)cp);else if(cp<=0x7ff){cvc_buf_putc(b,(unsigned char)(0xc0|(cp>>6)));cvc_buf_putc(b,(unsigned char)(0x80|(cp&63)));}else if(cp<=0xffff){if(cp>=0xd800&&cp<=0xdfff){fail(q,"surrogate scalar invalid");return;}cvc_buf_putc(b,(unsigned char)(0xe0|(cp>>12)));cvc_buf_putc(b,(unsigned char)(0x80|((cp>>6)&63)));cvc_buf_putc(b,(unsigned char)(0x80|(cp&63)));}else if(cp<=0x10ffff){cvc_buf_putc(b,(unsigned char)(0xf0|(cp>>18)));cvc_buf_putc(b,(unsigned char)(0x80|((cp>>12)&63)));cvc_buf_putc(b,(unsigned char)(0x80|((cp>>6)&63)));cvc_buf_putc(b,(unsigned char)(0x80|(cp&63)));}else fail(q,"Unicode scalar out of range");}
static int hv(unsigned char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int hex4(P*q,uint16_t*out){uint16_t v=0;for(int i=0;i<4;i++){if(eof(q)){fail(q,"incomplete Unicode escape");return -1;}int h=hv(getc_p(q));if(h<0){fail(q,"invalid hex digit in Unicode escape");return -1;}v=(uint16_t)((uint32_t)v * UINT32_C(16) + (uint32_t)h);}*out=v;return 0;}
static int parse_string_raw(P*q,CvcJString*out){if(getc_p(q)!='"'){fail(q,"expected string");return -1;}CvcBuf b;cvc_buf_init(&b);while(!eof(q)){unsigned char c=getc_p(q);if(c=='"'){if(!cvc_utf8_valid(b.data,b.len)){cvc_buf_free(&b);fail(q,"invalid UTF-8 in string");return -1;}out->p=b.data;out->n=b.len;return 0;}if(c<0x20){cvc_buf_free(&b);fail(q,"unescaped control byte in string");return -1;}if(c!='\\'){cvc_buf_putc(&b,c);continue;}if(eof(q)){cvc_buf_free(&b);fail(q,"unterminated escape");return -1;}c=getc_p(q);switch(c){case '"':case '\\':case '/':cvc_buf_putc(&b,c);break;case 'b':cvc_buf_putc(&b,'\b');break;case 'f':cvc_buf_putc(&b,'\f');break;case 'n':cvc_buf_putc(&b,'\n');break;case 'r':cvc_buf_putc(&b,'\r');break;case 't':cvc_buf_putc(&b,'\t');break;case 'u':{uint16_t a;if(hex4(q,&a)<0){cvc_buf_free(&b);return -1;}if(a>=0xd800&&a<=0xdbff){if(q->pos+2>q->n||q->p[q->pos]!='\\'||q->p[q->pos+1]!='u'){cvc_buf_free(&b);fail(q,"unpaired high surrogate");return -1;}getc_p(q);getc_p(q);uint16_t z;if(hex4(q,&z)<0){cvc_buf_free(&b);return -1;}if(z<0xdc00||z>0xdfff){cvc_buf_free(&b);fail(q,"invalid low surrogate");return -1;}uint32_t cp=0x10000u+(((uint32_t)a-0xd800u)<<10)+((uint32_t)z-0xdc00u);emit_cp(q,&b,cp);}else if(a>=0xdc00&&a<=0xdfff){cvc_buf_free(&b);fail(q,"unpaired low surrogate");return -1;}else emit_cp(q,&b,a);if(q->err){cvc_buf_free(&b);return -1;}break;}default:cvc_buf_free(&b);fail(q,"invalid string escape");return -1;}}cvc_buf_free(&b);fail(q,"unterminated string");return -1;}
static CvcJson*value(P*q);
static CvcJson*array(P*q){getc_p(q);CvcJson*j=node(J_ARRAY);ws(q);if(peek(q)==']'){getc_p(q);return j;}for(;;){CvcJson*x=value(q);if(!x){cvc_json_free(j);return NULL;}j->u.array.v=cvc_xrealloc(j->u.array.v,(j->u.array.n+1)*sizeof(*j->u.array.v));j->u.array.v[j->u.array.n++]=x;ws(q);unsigned char c=getc_p(q);if(c==']')return j;if(c!=','){fail(q,"expected ',' or ']' in array");cvc_json_free(j);return NULL;}ws(q);if(peek(q)==']'){fail(q,"trailing comma in array");cvc_json_free(j);return NULL;}}}
static int keyeq(CvcJString*a,CvcJString*b){return a->n==b->n&&!memcmp(a->p,b->p,a->n);}
static CvcJson*object(P*q){getc_p(q);CvcJson*j=node(J_OBJECT);ws(q);if(peek(q)=='}'){getc_p(q);return j;}for(;;){if(peek(q)!='"'){fail(q,"object key must be string");cvc_json_free(j);return NULL;}CvcJString k={0};if(parse_string_raw(q,&k)<0){cvc_json_free(j);return NULL;}for(size_t i=0;i<j->u.object.n;i++)if(keyeq(&j->u.object.v[i].key,&k)){free(k.p);fail(q,"duplicate object key");cvc_json_free(j);return NULL;}ws(q);if(getc_p(q)!=':'){free(k.p);fail(q,"expected ':' after object key");cvc_json_free(j);return NULL;}ws(q);CvcJson*x=value(q);if(!x){free(k.p);cvc_json_free(j);return NULL;}j->u.object.v=cvc_xrealloc(j->u.object.v,(j->u.object.n+1)*sizeof(*j->u.object.v));j->u.object.v[j->u.object.n].key=k;j->u.object.v[j->u.object.n].value=x;j->u.object.n++;ws(q);unsigned char c=getc_p(q);if(c=='}')return j;if(c!=','){fail(q,"expected ',' or '}' in object");cvc_json_free(j);return NULL;}ws(q);if(peek(q)=='}'){fail(q,"trailing comma in object");cvc_json_free(j);return NULL;}}}
static int lit(P*q,const char*s){size_t n=strlen(s);if(q->pos+n>q->n||memcmp(q->p+q->pos,s,n))return 0;for(size_t i=0;i<n;i++)getc_p(q);return 1;}
static CvcJson*number(P*q){size_t st=q->pos;if(peek(q)=='-')getc_p(q);if(eof(q)){fail(q,"incomplete number");return NULL;}if(peek(q)=='0'){getc_p(q);if(!eof(q)&&peek(q)>='0'&&peek(q)<='9'){fail(q,"leading zero in number");return NULL;}}else if(peek(q)>='1'&&peek(q)<='9'){while(!eof(q)&&peek(q)>='0'&&peek(q)<='9')getc_p(q);}else{fail(q,"invalid number integer component");return NULL;}if(!eof(q)&&peek(q)=='.'){getc_p(q);if(eof(q)||peek(q)<'0'||peek(q)>'9'){fail(q,"fraction requires digit");return NULL;}while(!eof(q)&&peek(q)>='0'&&peek(q)<='9')getc_p(q);}if(!eof(q)&&(peek(q)=='e'||peek(q)=='E')){getc_p(q);if(!eof(q)&&(peek(q)=='+'||peek(q)=='-'))getc_p(q);if(eof(q)||peek(q)<'0'||peek(q)>'9'){fail(q,"exponent requires digit");return NULL;}while(!eof(q)&&peek(q)>='0'&&peek(q)<='9')getc_p(q);}size_t n=q->pos-st;char*t=cvc_xstrndup((const char*)q->p+st,n);errno=0;char*end=NULL;double d=strtod(t,&end);if(errno==ERANGE||!isfinite(d)||!end||*end){free(t);fail(q,"number overflow or invalid numeric range");return NULL;}CvcJson*j=node(J_NUMBER);j->u.number.p=(unsigned char*)t;j->u.number.n=n;return j;}
static CvcJson*value(P*q){ws(q);if(eof(q)){fail(q,"expected JSON value");return NULL;}unsigned char c=peek(q);if(c=='{')return object(q);if(c=='[')return array(q);if(c=='"'){CvcJson*j=node(J_STRING);if(parse_string_raw(q,&j->u.string)<0){free(j);return NULL;}return j;}if(c=='-'||(c>='0'&&c<='9'))return number(q);if(lit(q,"true")){CvcJson*j=node(J_BOOL);j->u.boolean=1;return j;}if(lit(q,"false")){CvcJson*j=node(J_BOOL);return j;}if(lit(q,"null"))return node(J_NULL);fail(q,"invalid token");return NULL;}
int cvc_json_parse(const unsigned char*d,size_t n,CvcJson**out,char**err){*out=NULL;*err=NULL;if(n>=3&&d[0]==0xef&&d[1]==0xbb&&d[2]==0xbf){*err=cvc_xstrdup("line 1 column 1 byte 0: UTF-8 BOM is not allowed");return -1;}P q={d,n,0,1,1,NULL};CvcJson*j=value(&q);if(!j){*err=q.err?q.err:cvc_xstrdup("JSON parse error");return -1;}ws(&q);if(q.pos!=q.n){fail(&q,"trailing data after top-level value");cvc_json_free(j);*err=q.err;return -1;}*out=j;return 0;}
void cvc_json_free(CvcJson*j){if(!j)return;switch(j->type){case J_STRING:free(j->u.string.p);break;case J_NUMBER:free(j->u.number.p);break;case J_ARRAY:for(size_t i=0;i<j->u.array.n;i++)cvc_json_free(j->u.array.v[i]);free(j->u.array.v);break;case J_OBJECT:for(size_t i=0;i<j->u.object.n;i++){free(j->u.object.v[i].key.p);cvc_json_free(j->u.object.v[i].value);}free(j->u.object.v);break;default:break;}free(j);}
CvcJson*cvc_json_obj_get(const CvcJson*j,const char*k){if(!j||j->type!=J_OBJECT)return NULL;size_t n=strlen(k);for(size_t i=0;i<j->u.object.n;i++)if(j->u.object.v[i].key.n==n&&!memcmp(j->u.object.v[i].key.p,k,n))return j->u.object.v[i].value;return NULL;}
